import{_ as a,o as t,c as o,a6 as i}from"./chunks/framework.BJFjZBwW.js";const p=JSON.parse('{"title":"WebUI","description":"","frontmatter":{},"headers":[],"relativePath":"use/webui.md","filePath":"use/webui.md","lastUpdated":1754528373000}'),n={name:"use/webui.md"};function r(s,e,l,c,h,d){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h1><p>For ESP32 based environments a WebUI is available to provide basic configuration and monitoring of your OpenMQTTGateway Device. Functions included are:</p><ul><li>Configuration</li><li>Information</li><li>Firmware Upgrade</li><li>Console</li><li>Restart</li></ul><h1 id="login-authentication" tabindex="-1">Login Authentication <a class="header-anchor" href="#login-authentication" aria-label="Permalink to &quot;Login Authentication&quot;">​</a></h1><p>By default access to the WebUI uses basic authentication to control access to your OpenMQTTGateway Device. The login is <code>admin</code> and the password is your <code>gateway password</code> (if unchanged during onboarding there is no password).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The communication with the WebUI is not encrypted, which means that your data may be visible on your local network.</p></div><h1 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to &quot;Configuration Options&quot;">​</a></h1><h2 id="wifi" tabindex="-1">WiFi <a class="header-anchor" href="#wifi" aria-label="Permalink to &quot;WiFi&quot;">​</a></h2><p>Ability to change the SSID and password for your WiFi, if the change is unsuccessful it will revert back to the previous WiFi settings.</p><h2 id="mqtt" tabindex="-1">MQTT <a class="header-anchor" href="#mqtt" aria-label="Permalink to &quot;MQTT&quot;">​</a></h2><p>Ability to change the mqtt settings, if the change is unsuccessful it will revert back to the previous mqtt settings.</p><h2 id="webui-1" tabindex="-1">WebUI <a class="header-anchor" href="#webui-1" aria-label="Permalink to &quot;WebUI&quot;">​</a></h2><p>Ability to change the display of sensor to Metric or Imperial, and disable the WebUI Authentication</p><h2 id="bluetooth-low-energy-ble" tabindex="-1">Bluetooth Low Energy - BLE <a class="header-anchor" href="#bluetooth-low-energy-ble" aria-label="Permalink to &quot;Bluetooth Low Energy - BLE&quot;">​</a></h2><p>Ability to add the default AES BLE decryption key, and multiple per-device <code>macaddress:aeskey</code> allowing for devices that cannot have their AES key changed.</p><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><p>Ability to temporarily change the logging level.</p><h1 id="information" tabindex="-1">Information <a class="header-anchor" href="#information" aria-label="Permalink to &quot;Information&quot;">​</a></h1><p>Details of OpenMQTTGateway Device status</p><h1 id="firmware-upgrade" tabindex="-1">Firmware Upgrade <a class="header-anchor" href="#firmware-upgrade" aria-label="Permalink to &quot;Firmware Upgrade&quot;">​</a></h1><p>Ability to upgrade firmware by URL or to latest version.</p><h1 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h1><p>Ability to view messages from the OpenMQTTGateway console. The scope of messages visible in the UI is limited to just the OpenMQTTGateway codebase, messages from the ESP hardware or other libraries are not visible,</p><p>Ability to inject commands to OpenMQTTGateway for processing. The commands accepted are of the form mqtt topic then json message. And as you are already on the target device, you do not need to include the device name ie</p><p><code>commands/MQTTtoSYS/config {&quot;cmd&quot;:&quot;restart&quot;}</code></p><p>This works for all modules in your environment.</p>',26)])])}const b=a(n,[["render",r]]);export{p as __pageData,b as default};
